-- Run only against a disposable test database (scripts/test-db.sh).
begin;
create schema tests;
create table tests.context(key text primary key,value text);
grant usage on schema tests to anon,authenticated;
grant all on tests.context to anon,authenticated;
create function tests.assert(ok boolean, label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end; $$;
create function tests.rejects(command text,label text) returns void language plpgsql as $$
declare rejected boolean := false;
begin
 begin execute command; exception when others then rejected:=true; end;
 if not rejected then raise exception 'FAIL (unexpectedly allowed): %',label; end if;
 raise notice 'PASS: %',label;
end; $$;
grant execute on all functions in schema tests to anon,authenticated;
insert into auth.users values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into tests.context values('trip',public.create_trip('{"name":"Goa escape","description":"Together","minimum_participants":3,"options":[{"destination":"Goa","start_date":"2027-01-01","end_date":"2027-01-03","estimated_cost":12000},{"destination":"Coorg","start_date":"2027-02-01","end_date":"2027-02-03","estimated_cost":15000}],"invitees":["Maya","Arjun"]}')::text);
insert into tests.context select 'token',invitation_token from public.trips;
insert into tests.context select 'option',id::text from public.trip_options where destination='Goa';
insert into tests.context select 'named_token',token from public.invitations where name='Maya';
insert into tests.context select 'named_id',id::text from public.invitations where name='Maya';
select tests.assert((select count(*)=1 from public.trips),'owner reads own trip');
select tests.assert((select count(*)=2 from public.trip_options),'all proposed options persisted');
select tests.assert((select count(*)=2 from public.invitations),'real invitation list persisted');
select tests.rejects($cmd$select public.create_trip('{"name":"bad","description":"","minimum_participants":2,"options":[],"invitees":[]}')$cmd$,'empty travel options rejected');
select tests.rejects($cmd$select public.create_trip('{"name":"bad","description":"","minimum_participants":2.5,"options":[{"destination":"Goa","start_date":"2027-01-01","end_date":"2027-01-03","estimated_cost":12000}],"invitees":[]}')$cmd$,'fractional minimum rejected');
select tests.rejects($cmd$select public.create_trip('{"name":"bad","description":"","minimum_participants":2,"options":[{"destination":"Goa","start_date":"2027-01-03","end_date":"2027-01-01","estimated_cost":12000}],"invitees":[]}')$cmd$,'reversed dates rejected');
select tests.rejects($cmd$select public.create_trip('{"name":"bad","description":"","minimum_participants":2,"options":[{"destination":"Goa","start_date":"2027-02-30","end_date":"2027-03-03","estimated_cost":12000}],"invitees":[]}')$cmd$,'impossible dates rejected');
select tests.rejects($cmd$select public.create_trip('{"name":"bad","description":"","minimum_participants":2,"options":[{"destination":"Goa","start_date":"2027-01-01","end_date":"2027-01-03","estimated_cost":1.001}],"invitees":[]}')$cmd$,'fractional paise rejected');
select tests.assert((select count(*)=1 from public.trips),'invalid trip transactions leave no partial rows');
select tests.rejects($cmd$update public.trips set name='hijacked'$cmd$,'direct trip mutation denied even for owner');
select tests.rejects(format('select public.add_invitees(%L,array[%L])',(select value from tests.context where key='trip'),' maya '),'duplicate named invitations rejected');
-- Another signed-in leader must not read or alter the first leader's data.
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select tests.assert((select count(*)=0 from public.trips),'other leader cannot read trips');
select tests.assert((select count(*)=0 from public.trip_options),'other leader cannot read options');
select tests.assert((select count(*)=0 from public.invitations),'other leader cannot read invitation list');
select tests.assert((select count(*)=0 from public.responses),'other leader cannot read responses');
select tests.rejects(format('select public.add_invitees(%L,array[%L])',(select value from tests.context where key='trip'),'Intruder'),'other leader cannot add invitees');
insert into tests.context values('other_trip',public.create_trip('{"name":"Other trip","description":"","minimum_participants":2,"options":[{"destination":"Delhi","start_date":"2027-01-01","end_date":"2027-01-03","estimated_cost":10}],"invitees":[]}')::text);
insert into tests.context select 'other_option',id::text from public.trip_options;
insert into tests.context select 'other_token',invitation_token from public.trips;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select tests.rejects('select * from public.trips','anonymous direct trip read denied');
select tests.rejects('select * from public.trip_options','anonymous direct options read denied');
select tests.rejects('select * from public.invitations','anonymous invitation-list read denied');
select tests.rejects('select name from public.responses','anonymous response read denied');
select tests.rejects($cmd$select public.create_trip('{}')$cmd$,'anonymous trip creation denied');
select tests.assert(public.get_invitation('invalid') is null,'invalid invitation reveals nothing');
select tests.assert(public.get_own_response('invalid') is null,'invalid edit token reveals nothing');
select tests.assert((public.get_invitation((select value from tests.context where key='token'))->>'name')='Goa escape','public invitation exposes trip name');
select tests.assert(jsonb_array_length(public.get_invitation((select value from tests.context where key='token'))->'options')=2,'public invitation exposes proposed options');
select tests.assert(not(public.get_invitation((select value from tests.context where key='token')) ?| array['responses','owner_id','invitation_token','invitees']),'invitation metadata excludes private data');
select tests.assert(public.get_invitation((select value from tests.context where key='named_token'))->>'invited_name'='Maya','personal invitation prefills only its own invitee');
insert into tests.context values('payload',jsonb_build_object('name','Guest','available_option_ids',jsonb_build_array((select value from tests.context where key='option')),'max_budget',15000,'preferred_destinations',jsonb_build_array('Goa'),'interests',jsonb_build_array('Food'),'commitment','Interested','invitation_id',(select value from tests.context where key='named_id'))::text);
select tests.rejects(format('select public.submit_response(%L,%L::jsonb)', 'invalid',(select value from tests.context where key='payload')),'invalid invitation cannot submit');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb)',(select value from tests.context where key='token'),(select jsonb_set(value::jsonb,'{available_option_ids}',jsonb_build_array((select value from tests.context where key='other_option')))::text from tests.context where key='payload')),'options from another trip rejected');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb)',(select value from tests.context where key='token'),(select jsonb_set(value::jsonb,'{preferred_destinations}','["Mars"]')::text from tests.context where key='payload')),'unproposed destinations rejected');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb)',(select value from tests.context where key='token'),(select jsonb_set(value::jsonb,'{max_budget}','-1')::text from tests.context where key='payload')),'negative budget rejected');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb)',(select value from tests.context where key='token'),(select jsonb_set(value::jsonb,'{commitment}','"Booked"')::text from tests.context where key='payload')),'unknown commitment rejected');
insert into tests.context values('edit',public.submit_response((select value from tests.context where key='token'),(select value::jsonb from tests.context where key='payload')));
select tests.assert(length((select value from tests.context where key='edit'))=64,'response gets 256-bit private edit capability');
select tests.assert(public.get_own_response((select value from tests.context where key='token')) is null,'invitation token cannot read a response');
select tests.assert(public.get_own_response((select value from tests.context where key='edit'))->>'name'='Guest','edit capability reads its own response');
select tests.assert(public.get_own_response((select value from tests.context where key='edit'))->>'invitation_id' is null,'general submission cannot forge named invitation association');
select tests.assert(not(public.get_own_response((select value from tests.context where key='edit')) ? 'edit_token_hash'),'private read never returns capability hash');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb,%L)',(select value from tests.context where key='token'),(select value from tests.context where key='payload'),repeat('0',64)),'forged edit capability cannot update');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb,%L)',(select value from tests.context where key='other_token'),(select jsonb_build_object('name','Guest','available_option_ids',jsonb_build_array((select value from tests.context where key='other_option')),'max_budget',10,'preferred_destinations',jsonb_build_array('Delhi'),'interests',jsonb_build_array('Food'),'commitment','Confirmed')::text),(select value from tests.context where key='edit')),'edit capability cannot cross trip boundary');
select public.submit_response((select value from tests.context where key='token'),(select jsonb_set(value::jsonb,'{commitment}','"Confirmed"') from tests.context where key='payload'),(select value from tests.context where key='edit')) is not null as updated;
select tests.assert(public.get_own_response((select value from tests.context where key='edit'))->>'commitment'='Confirmed','private capability updates existing response');
insert into tests.context values('named_edit',public.submit_response((select value from tests.context where key='named_token'),(select value::jsonb from tests.context where key='payload')));
select tests.assert(public.get_own_response((select value from tests.context where key='named_edit'))->>'invitation_id'=(select value from tests.context where key='named_id'),'personal response is linked to real invitation');
select tests.rejects(format('select public.submit_response(%L,%L::jsonb)',(select value from tests.context where key='named_token'),(select value from tests.context where key='payload')),'personal invite cannot overwrite existing response without edit capability');
-- The organizer can see preferences, but does not receive the private edit capability.
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select tests.assert((select count(*)=2 from public.responses),'owner sees both responses with update not duplicate');
select tests.assert((select count(*)=1 from public.responses where invitation_id is not null),'only a personal invitation counts toward named response progress');
select tests.rejects('select edit_token_hash from public.responses','owner cannot retrieve response edit hashes');
select tests.assert((select count(*)=2 from public.trip_options),'owner still sees original options');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select tests.assert((select count(*)=0 from public.responses),'other leader cannot read submitted responses');
select tests.rejects('update public.responses set name=''hijack''','direct response edits denied');
reset role;
rollback;
